python3 - <<'PY'
from pathlib import Path

def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{path}: expected one match, got {count}: {old!r}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')

# Align existing valid task fixtures with the explicit resources contract.
p='tests/test_agent_runtime.py'
replace_once(p, '            "id": "efficient-task",\n            "workflow_policy":', '            "id": "efficient-task",\n            "resources": [],\n            "workflow_policy":')
replace_once(p, '            "id": "staged-1",\n            "steps":', '            "id": "staged-1",\n            "resources": [],\n            "steps":')
replace_once(p, '                    "id": "large-patch",\n                    "patch":', '                    "id": "large-patch",\n                    "resources": [],\n                    "patch":')
replace_once(p, '                    "id": "many-commands",\n                    "commands":', '                    "id": "many-commands",\n                    "resources": [],\n                    "commands":')
replace_once(p, '                    "id": "bad-stage-timeout",\n                    "steps":', '                    "id": "bad-stage-timeout",\n                    "resources": [],\n                    "steps":')
replace_once(p, '                "id": "heavy-task",\n                "commands":', '                "id": "heavy-task",\n                "resources": [],\n                "commands":')
replace_once(p, '                "id": "legacy-structured",\n                "steps":', '                "id": "legacy-structured",\n                "resources": [],\n                "steps":')
replace_once(p, '            "id": "slow-progress-callback",\n            "commands":', '            "id": "slow-progress-callback",\n            "resources": [],\n            "commands":')
replace_once(p, '            "id": "stage-timeout-override",\n            "steps":', '            "id": "stage-timeout-override",\n            "resources": [],\n            "steps":')

p='tests/test_agentd.py'
replace_once(p, '        return {"id": task_id, "mode": "commands", "commands": ["true"]}', '        return {"id": task_id, "mode": "commands", "resources": [], "commands": ["true"]}')

p='tests/test_runtime_task_contract_module.py'
replace_once(p, '        task = {"id": "contract-smoke", "commands": ["true"], "command_timeout": 60, "task_timeout": 180}', '        task = {"id": "contract-smoke", "resources": [], "commands": ["true"], "command_timeout": 60, "task_timeout": 180}')

# NEXT is an idempotent conversation-local arm/re-arm command. It deliberately
# does not override the global master switch.
p='chat_bridge/service_worker.js'
replace_once(
    p,
    '    "Bridge v0.3 controls are conversation-scoped. Prefer short final-line controls: [LAB:STOP], [LAB:PAUSE], [LAB:RESUME], [LAB:NEXT=30s], [LAB:NEXT=10m], [LAB:INTERVAL=30m], [LAB:INTERVAL=AUTO]. NEXT changes only the next wake, not the normal interval."',
    '    "Bridge v0.3 controls are conversation-scoped. Prefer short final-line controls: [LAB:STOP], [LAB:PAUSE], [LAB:RESUME], [LAB:NEXT=30s], [LAB:NEXT=10m], [LAB:INTERVAL=30m], [LAB:INTERVAL=AUTO]. NEXT arms or re-arms this conversation and changes only its next wake, not the normal interval or global master switch."'
)
old='''  if (parsed.action === "next") {
    await updateConversationStatus(conversation.id, {
      ...common,
      lastStatus: `next_${parsed.seconds}s_by_assistant`
    });
    const updated = await getBridgeState();
    if (updated.settings.masterEnabled && updated.conversations[conversation.id]?.enabled) {
      await scheduleAfterSeconds(conversation.id, parsed.seconds);
    }
    return {
      ok: true,
      reason: "next_scheduled",
      seconds: parsed.seconds,
      conversationId: conversation.id
    };
  }
'''
new='''  if (parsed.action === "next") {
    await updateConversationStatus(conversation.id, {
      ...common,
      enabled: true,
      lastStatus: `next_${parsed.seconds}s_by_assistant`
    });
    const updated = await getBridgeState();
    const scheduled = updated.settings.masterEnabled
      ? await scheduleAfterSeconds(conversation.id, parsed.seconds)
      : false;
    return {
      ok: true,
      reason: scheduled ? "next_scheduled" : "next_armed_master_disabled",
      armed: true,
      seconds: parsed.seconds,
      conversationId: conversation.id
    };
  }
'''
replace_once(p, old, new)

# Regression: PAUSE disables a conversation, then NEXT alone must re-arm it.
p='chat_bridge/service_worker.test.js'
anchor='''  assert.equal(response.state.conversations[aId].enabled, false);
  assert.equal(response.state.conversations[bId].enabled, true);
  assert.equal(alarms.has(`local-agent-chat:${aId}`), false);
  assert.equal(alarms.has(`local-agent-chat:${bId}`), true);

  const beforeNext = Date.now();
'''
replacement='''  assert.equal(response.state.conversations[aId].enabled, false);
  assert.equal(response.state.conversations[bId].enabled, true);
  assert.equal(alarms.has(`local-agent-chat:${aId}`), false);
  assert.equal(alarms.has(`local-agent-chat:${bId}`), true);

  const beforeRearm = Date.now();
  response = await sendRuntimeMessage(
    {
      type: "bridge:assistant-control",
      conversationUrl: "https://chatgpt.com/c/a",
      fingerprint: "cdef3456",
      control: { marker: "[LAB:NEXT=30s]" }
    },
    { tab: { url: "https://chatgpt.com/c/a" } }
  );
  assert.equal(response.ok, true);
  assert.equal(response.reason, "next_scheduled");
  assert.equal(response.armed, true);
  response = await sendRuntimeMessage({ type: "bridge:get-state" });
  assert.equal(response.state.conversations[aId].enabled, true);
  const rearmedAlarm = alarms.get(`local-agent-chat:${aId}`);
  assert.ok(rearmedAlarm.when >= beforeRearm + 29_000);
  assert.ok(rearmedAlarm.when <= beforeRearm + 31_500);

  const beforeNext = Date.now();
'''
replace_once(p, anchor, replacement)

# Canonical planner contract: unfinished loop always emits a NEXT marker.
p='docs/AUTONOMOUS_CHAT_LOOP.md'
replace_once(
    p,
    '9. Otherwise leave bridge automation enabled. Use a one-shot `NEXT` marker only when changing the next wake time is useful.',
    '9. Otherwise end the response with a one-shot `NEXT` marker at an appropriate cadence. `NEXT` is the durable keep-alive: it arms or re-arms this conversation even if an earlier conversation-local `STOP`/`PAUSE` disabled it.'
)
replace_once(
    p,
    '`NEXT` changes only the next bridge alarm. It does not change Local Agent polling, duplicate task execution, or the rule that only one task for the active conversation goal is followed at a time.',
    '`NEXT` arms or re-arms this conversation and changes only its next bridge alarm. It does not enable the global master switch, change the persistent interval, alter Local Agent polling, permit duplicate task execution, or change the rule that only one task for the active conversation goal is followed at a time.'
)
replace_once(
    p,
    '- `NEXT=<duration>`: change only the next wake time. Supported durations are seconds (`s`) or minutes (`m`), bounded from 30 seconds through 24 hours.',
    '- `NEXT=<duration>`: arm or re-arm this conversation and set its next wake time. It does not override the global master switch or persistent interval. Supported durations are seconds (`s`) or minutes (`m`), bounded from 30 seconds through 24 hours.'
)
replace_once(
    p,
    '  "allow_write": false,\n  "command_timeout": 60,',
    '  "allow_write": false,\n  "resources": [],\n  "command_timeout": 60,'
)

p='chat_bridge/README.md'
replace_once(
    p,
    '- `NEXT=<duration>` schedules only the next wake and does not change the normal interval. Durations are bounded to 30 seconds through 24 hours.',
    '- `NEXT=<duration>` arms or re-arms that conversation and schedules its next wake without changing the normal interval. It never overrides the global master switch. Durations are bounded to 30 seconds through 24 hours.'
)
PY

